import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load texture using cached loader
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Create material for plane
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(1, 1);

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene transforms from config.scenePosition
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ, scaleXYZ } = config.scenePosition;
    mesh.position.set(x, y, z);

    if (rotationXYZ) {
      mesh.rotation.order = 'XYZ';
      mesh.rotation.set(rotationXYZ[0], rotationXYZ[1], rotationXYZ[2]);
    }

    if (scaleXYZ) {
      mesh.scale.set(scaleXYZ[0], scaleXYZ[1], scaleXYZ[2]);
    }
  }

  group.add(mesh);

  // Cleanup function — dispose of resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // Event handlers (no interactions on this card)
  group.userData.handlers = {};

  return group;
}
